<?php
require __DIR__.'/bootstrap.php'; require_login(); $me=user();
$canEdit=can('shipments.create')||can('shipments.edit');
if($_SERVER['REQUEST_METHOD']==='POST'){
    require_roles(['super_admin','admin','staff']); verify_csrf();
    if(isset($_POST['bulk_delete'])){require_perm('shipments.delete');
        $idsRaw=$_POST['ids']??[];if(!is_array($idsRaw))$idsRaw=is_string($idsRaw)&&$idsRaw!==''?[$idsRaw]:[];$ids=[];foreach($idsRaw as $x){$n=(int)$x;if($n>0)$ids[]=$n;}
        if($ids){try{$ph=implode(',',array_map(fn($x)=>'?',$ids));$pdo->beginTransaction();$allow=is_admin();$allowed=[];$check=$pdo->prepare("SELECT id FROM shipments WHERE id IN ($ph)".($allow?'':' AND branch_id='.(int)$me['branch_id']));$check->execute($ids);foreach($check->fetchAll() as $row)$allowed[]=(int)$row['id'];$own=[];foreach($ids as $x)if($allow||in_array($x,$allowed,true))$own[]=$x;if($own){$ph2=implode(',',array_map(fn($x)=>'?',$own));$pdo->prepare("DELETE FROM bank_transactions WHERE source_table='payments' AND source_id IN (SELECT id FROM payments WHERE shipment_id IN ($ph2))")->execute($own);$pdo->prepare("DELETE FROM shipment_invoices WHERE shipment_id IN ($ph2)")->execute($own);$pdo->prepare("DELETE FROM shipments WHERE id IN ($ph2)")->execute($own);}$pdo->commit();flash('success',count($own).' shipment(s) deleted.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Some shipments could not be deleted.');}}
        redirect('cargo.php');
    }
    if(isset($_POST['delete'])){require_perm('shipments.delete');
        try{$id=(int)$_POST['id'];$pdo->beginTransaction();$check='SELECT id FROM shipments WHERE id=?'.(is_admin()?'':' AND branch_id=?');$args=is_admin()?[$id]:[$id,(int)$me['branch_id']];$s=$pdo->prepare($check);$s->execute($args);if(!$s->fetch())throw new RuntimeException();$pdo->prepare("DELETE FROM bank_transactions WHERE source_table='payments' AND source_id IN (SELECT id FROM payments WHERE shipment_id=?)")->execute([$id]);$pdo->prepare('DELETE FROM shipment_invoices WHERE shipment_id=?')->execute([$id]);$pdo->prepare('DELETE FROM shipments WHERE id=?')->execute([$id]);$pdo->commit();flash('success','Shipment and its linked invoice/payment records were deleted.');}
        catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Shipment could not be deleted.');}
        redirect('cargo.php');
    }
    if(!is_admin())$_POST['branch_id']=(int)require_branch();
    $shipmentBranch=(int)($_POST['branch_id']??require_branch());
    $toBranch=(int)($_POST['to_branch_id']??0);if(!$toBranch)$toBranch=$shipmentBranch;
    if((int)($_POST['airline_id']??0)<1)$_POST['airline_id']=(int)$pdo->query('SELECT id FROM airlines WHERE active=1 ORDER BY id LIMIT 1')->fetchColumn();
    $fields=[trim($_POST['shipment_date']),strtoupper(trim($_POST['awb'])),trim($_POST['mark']),max(1,(int)$_POST['pcs']),(float)$_POST['kg'],(float)$_POST['rate'],(float)($_POST['paid_dxb']??0),(float)($_POST['extra']??0),trim($_POST['sender']),trim($_POST['tell']),trim($_POST['receiver']),trim($_POST['receiver_phone']??''),trim($_POST['description']),(int)$_POST['airline_id'],trim($_POST['fly_awb_no']),$_POST['status'],$_POST['customer_id']?:null];
    $payment=$fields[6]<=0?'Unpaid':($fields[6]>=($fields[4]*$fields[5])?'Paid':'Partially Paid');
    if(isset($_POST['create'])){require_perm('shipments.create');
        $pdo->beginTransaction();
        try{
            $pdo->prepare('INSERT INTO shipments(shipment_date,awb,mark,pcs,kg,rate,paid_dxb,extra,sender,tell,receiver,receiver_phone,description,airline_id,fly_awb_no,status,customer_id,payment_receive,branch_id,to_branch_id,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([...$fields,$payment,$shipmentBranch,$toBranch,$me['id']]);
            $shipmentId=(int)$pdo->lastInsertId();
            $invNo=create_shipment_invoice($shipmentId,round((float)$fields[4]*(float)$fields[5],2),(string)$me['id']);
            $pdo->commit();
            flash('success',"Shipment {$fields[1]} registered — invoice $invNo created automatically.");
        }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Shipment could not be registered — check that the AWB is unique and try again.');}
    } elseif(isset($_POST['update'])){
        require_perm('shipments.edit');
        $scope=is_admin()?'':' AND branch_id='.require_branch();
        $pdo->prepare('UPDATE shipments SET shipment_date=?,awb=?,mark=?,pcs=?,kg=?,rate=?,paid_dxb=?,extra=?,sender=?,tell=?,receiver=?,receiver_phone=?,description=?,airline_id=?,fly_awb_no=?,status=?,customer_id=?,payment_receive=?,branch_id=?,to_branch_id=? WHERE id=?'.$scope)->execute([...$fields,$payment,$shipmentBranch,$toBranch,(int)$_POST['id']]); flash('success','Shipment updated.');
    }
    redirect('cargo.php');
}
$conditions=[];$params=[];
if(!is_admin()){$conditions[]='(s.branch_id=? OR s.to_branch_id=?)';$params[]=(int)$me['branch_id'];$params[]=(int)$me['branch_id'];}
if($me['role']==='customer'){$conditions[]='s.customer_id=?';$params[]=$me['id'];}
if(trim($_GET['q']??'')!==''){$conditions[]='(s.awb LIKE ? OR s.sender LIKE ? OR s.fly_awb_no LIKE ?)';$term='%'.trim($_GET['q']).'%';array_push($params,$term,$term,$term);}
if($_GET['from']??''){$conditions[]='s.shipment_date>=?';$params[]=$_GET['from'];}if($_GET['to']??''){$conditions[]='s.shipment_date<=?';$params[]=$_GET['to'];}
if($_GET['airline']??''){$conditions[]='s.airline_id=?';$params[]=$_GET['airline'];}if($_GET['payment']??''){$conditions[]='s.payment_receive=?';$params[]=$_GET['payment'];}if($_GET['awb_group']??''){$conditions[]='ga.awb_no=?';$params[]=$_GET['awb_group'];}
$where=$conditions?'WHERE '.implode(' AND ',$conditions):'';
$sql="SELECT s.*,a.name airline,a.code airline_code,u.name customer,ga.id awb_group_id,ga.awb_no awb_group FROM shipments s JOIN airlines a ON a.id=s.airline_id LEFT JOIN users u ON u.id=s.customer_id LEFT JOIN shipment_awb_members gam ON gam.shipment_id=s.id LEFT JOIN shipment_awbs ga ON ga.id=gam.awb_id $where ORDER BY s.shipment_date DESC,s.id DESC";$stmt=$pdo->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();
if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="shipments-'.date('Y-m-d').'.csv"');$o=fopen('php://output','w');fputcsv($o,['DATE','AWB','MARK','PCS','KG','RATE','TOTAL','PAID DXB','BALANCE MGQ','EXTRA','SENDER','TELL','RECEIVER','RECEIVER PHONE','DESCRIPTION','PAYMENT RECEIVE','FLY NAME','FLY AWB NO','AWB GROUP','STATUS']);foreach($rows as $r)fputcsv($o,[$r['shipment_date'],$r['awb'],$r['mark'],$r['pcs'],$r['kg'],$r['rate'],$r['total'],$r['paid_dxb'],$r['balance_mgq'],$r['extra'],$r['sender'],$r['tell'],$r['receiver'],$r['receiver_phone']?:'', $r['description'],$r['payment_receive'],$r['airline'],$r['fly_awb_no'],$r['awb_group'],$r['status']]);fclose($o);exit;}
$airlines=$pdo->query('SELECT * FROM airlines WHERE active=1 ORDER BY name')->fetchAll();$awbGroupsList=$pdo->query("SELECT ga.id,ga.awb_no FROM shipment_awbs ga".(is_admin()?'':' WHERE ga.branch_id='.(int)require_branch()).' ORDER BY ga.awb_no DESC')->fetchAll();$customerSql="SELECT id,name,phone,account_no FROM users WHERE role='customer' AND active=1";if(!is_admin())$customerSql.=' AND (branch_id='.(int)require_branch().' OR branch_id IS NULL)';$customers=$canEdit?$pdo->query($customerSql.' ORDER BY name')->fetchAll():[];$senders=$canEdit?$pdo->query("SELECT sender, MAX(tell) tell FROM shipments WHERE TRIM(sender)<>'' GROUP BY sender ORDER BY MAX(id) DESC LIMIT 300")->fetchAll():[];$branches=$pdo->query('SELECT id,name,code FROM branches WHERE active=1 ORDER BY name')->fetchAll();$edit=null;if(isset($_GET['edit'])&&$canEdit){$s=$pdo->prepare('SELECT * FROM shipments WHERE id=?'.(is_admin()?'':' AND branch_id=?'));$s->execute(is_admin()?[(int)$_GET['edit']]:[(int)$_GET['edit'],require_branch()]);$edit=$s->fetch();}
