 status-<?=strtolower(str_replace(' ','-',$r['payment_receive']))?>"><?=e($r['payment_receive'])?></span></td><td><?=e($r['status'])?></td><?php if(can('shipments.edit')):?><td><a class="btn btn-sm btn-outline-secondary" href="?edit=<?=$r['id']?>">Edit</a></td><?php endif?></tr><?php endforeach?></tbody></table><?php if($rows&&can('shipments.delete')):?><form method="post" id="bulkDeleteForm" class="mt-3 d-flex align-items-center gap-2 d-print-none"><input type="hidden" name="csrf" value="<?=csrf()?>"><a class="btn btn-sm btn-outline-primary" id="bulkGroupBtn" href="#"><i class="bi bi-collection"></i> Group selected</a><button class="btn btn-sm btn-outline-danger" name="bulk_delete" data-confirm="Delete the selected shipment(s) and their invoices?"><i class="bi bi-trash"></i> Delete selected</button><span class="small text-secondary" id="bulkCount">0 selected</span></form><?php endif?><?php if(!$rows):?><div class="text-center text-secondary py-5">No shipments match the selected filters.</div><?php endif?></div></div><script>window.addEventListener("DOMContentLoaded",()=>{const all=document.querySelector("#selectAll");if(!all)return;const boxes=[...document.querySelectorAll(".row-check")],count=document.querySelector("#bulkCount");const up=()=>{const n=boxes.filter(b=>b.checked).length;count.textContent=n+" selected";all.checked=n>0&&n===boxes.length};all.onchange=()=>{boxes.forEach(b=>b.checked=all.checked);up()};boxes.forEach(b=>b.addEventListener("change",up));document.querySelector("#bulkDeleteForm")?.addEventListener("submit",e=>{const picked=boxes.filter(b=>b.checked).map(b=>b.value);const holder=document.createElement("div");picked.forEach(v=>{const i=document.createElement("input");i.type="hidden";i.name="ids[]";i.value=v;holder.append(i)});e.target.append(holder)})})</script><script>window.addEventListener("DOMContentLoaded",()=>{const g=document.querySelector("#bulkGroupBtn");if(!g)return;g.addEventListener("click",e=>{e.preventDefault();const picked=[...document.querySelectorAll(".row-check")].filter(b=>b.checked).map(b=>b.value);if(!picked.length){alert("Select at least one shipment to group.");return}location.href="shipment_awb.php?add="+picked.join(",")})})</script>
<?php if($canEdit):$v=$edit?:['id'=>'','shipment_date'=>date('Y-m-d'),'awb'=>'','mark'=>'','pcs'=>1,'kg'=>'','rate'=>'','paid_dxb'=>0,'extra'=>0,'sender'=>'','tell'=>'','receiver'=>'','receiver_phone'=>'','description'=>'','airline_id'=>'','fly_awb_no'=>'','status'=>'Pending','customer_id'=>'','branch_id'=>$me['branch_id'],'to_branch_id'=>$me['branch_id']];?><div class="modal fade" id="shipment"><div class="modal-dialog modal-xl"><form method="post" class="modal-content"><div class="modal-header"><h2 class="h5 mb-0"><?=$edit?'Update':'Register'?> shipment</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=e($v['id'])?>"><div class="row g-3"><div class="col-md-3"><label class="form-label">Date</label><input class="form-control" type="date" name="shipment_date" value="<?=e($v['shipment_date'])?>" required></div><div class="col-md-3"><label class="form-label">AWB</label><input class="form-control" name="awb" value="<?=e($v['awb'])?>" required></div><div class="col-md-3"><label class="form-label">Mark</label><input class="form-control" name="mark" value="<?=e($v['mark'])?>"></div><div class="col-md-3"><label class="form-label">Pieces</label><input class="form-control" type="number" min="1" name="pcs" value="<?=e($v['pcs'])?>" required></div><div class="col-md-3"><label class="form-label">KG</label><input id="kg" class="form-control calc" type="number" min=".01" step=".01" name="kg" value="<?=e($v['kg'])?>" required></div><div class="col-md-3"><label class="form-label">Rate / KG</label><input id="rate" class="form-control calc" type="number" min="0" step=".01" name="rate" value="<?=e($v['rate'])?>" required></div><div class="col-md-3"><label class="form-label">Total (KG × Rate)</label><input id="totalPreview" class="form-control" readonly></div><div class="col-md-3"><label class="form-label">Origin branch</label><select class="form-select" name="branch_id" required<?=is_admin()?'':' disabled'?>><?php foreach($branches as $b):?><option value="<?= $b['id']?>" <?= $v['branch_id']==$b['id']?'selected':''?>><?=e($b['name'].' ('.$b['code'].')')?></option><?php endforeach?></select></div><div class="col-md-3"><label class="form-label">Destination branch</label><select class="form-select" name="to_branch_id" required><?php foreach($branches as $b):?><option value="<?= $b['id']?>" <?= (int)$v['to_branch_id']==(int)$b['id']?'selected':''?>><?=e($b['name'].' ('.$b['code'].')')?></option><?php endforeach?></select></div><div class="col-md-3"><label class="form-label">Paid DXB</label><input id="paid" class="form-control calc" type="number" min="0" step=".01" name="paid_dxb" value="<?=e($v['paid_dxb'])?>"></div><div class="col-md-3"><label class="form-label">Balance MGQ</label><input id="balancePreview" class="form-control" readonly></div><div class="col-md-3"><label class="form-label">Extra</label><input class="form-control" type="number" min="0" step=".01" name="extra" value="<?=e($v['extra'])?>"></div><div class="col-md-3"><label class="form-label">Sender</label><input id="sender" class="form-control" name="sender" value="<?=e($v['sender'])?>" required list="senderList" placeholder="Type or choose an existing sender"><datalist id="senderList"><?php foreach($senders as $s):?><option value="<?=e($s['sender'])?>"<?= $s['tell']? ' data-tell="'.e($s['tell']).'"':''?>><?=e($s['tell']??'')?></option><?php endforeach?></datalist></div><div class="col-md-3"><label class="form-label">Tell</label><input id="tell" class="form-control" name="tell" value="<?=e($v['tell'])?>"></div><div class="col-md-3"><label class="form-label">Receiver</label><input class="form-control" name="receiver" value="<?=e($v['receiver'])?>" required></div><div class="col-md-3"><label class="form-label">Receiver Tell</label><input class="form-control" name="receiver_phone" value="<?=e($v['receiver_phone']??'')?>"></div><div class="col-md-3"><label class="form-label">Description</label><input class="form-control" name="description" value="<?=e($v['description'])?>" required></div><input type="hidden" name="airline_id" value="<?=(int)$v['airline_id']?>"><input type="hidden" name="fly_awb_no" value="<?=e($v['fly_awb_no']??'')?>"><div class="col-md-3"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['Pending','In Transit','Arrived','Delivered','Cancelled'] as $x):?><option <?=$v['status']===$x?'selected':''?>><?=$x?></option><?php endforeach?></select></div><div class="col-md-4"><label class="form-label">Customer account</label><select id="customer_id" class="form-select" name="customer_id"><option value="">Not linked</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" data-phone="<?=e($c['phone']??'')?>" <?=$v['customer_id']==$c['id']?'selected':''?>><?=e($c['name'].($c['account_no']?' · '.$c['account_no']:''))?></option><?php endforeach?></select><div class="form-text">Existing customer? Select their account to reuse it — auto-fills Sender &amp; phone.</div></div></div></div><div class="modal-footer"><button class="btn btn-primary" name="<?=$edit?'update':'create'?>">Save shipment</button></div></form></div></div><script>(function(){const sel=document.getElementById('customer_id');if(!sel)return;const frm=sel.closest('form');const fill=()=>{const o=sel.options[sel.selectedIndex];if(!o||o.value==='')return;const set=(n,v)=>{if(!v)return;const el=frm&&frm[n];if(el&&el.value==='')el.value=v;};set('sender',(o.textContent||'').split('·')[0].trim());if(o.dataset.phone)set('tell',o.dataset.phone);};sel.addEventListener('change',fill);})();const SENDERS=<?=json_encode($senders??[],JSON_UNESCAPED_UNICODE)?>;(function(){const s=document.getElementById('sender'),f=s&&s.closest('form');if(!s)return;const pick=()=>{const n=(s.value||'').trim().toLowerCase();if(!n||!f)return;const hit=(SENDERS||[]).find(o=>String(o.sender||'').trim().toLowerCase()===n);if(hit&&f.tell&&!f.tell.value)f.tell.value=hit.tell||'';};s.addEventListener('input',pick);s.addEventListener('change',pick);})();</script><script>const calc=()=>{const t=(+document.querySelector('#kg').value||0)*(+document.querySelector('#rate').value||0);document.querySelector('#totalPreview').value=t.toFixed(2);document.querySelector('#balancePreview').value=(t-(+document.querySelector('#paid').value||0)).toFixed(2)};document.querySelectorAll('.calc').forEach(x=>x.addEventListener('input',calc));calc();<?php if($edit):?>new bootstrap.Modal(document.querySelector('#shipment')).show();<?php endif?></script><?php endif?>
